<article class="gamification-detail"><header><p><?php echo utf8_htmlentities($match['starts_at'] ?? '') ?></p><h1><?php echo utf8_htmlentities($match['title']) ?></h1></header><div class="gamification-score"><strong><?php echo utf8_htmlentities($match['home_name']) ?></strong><span><?php echo $match['score_home'] === NULL ? $this->lang('VS') : (int)$match['score_home'].' - '.(int)$match['score_away'] ?></span><strong><?php echo utf8_htmlentities($match['away_name']) ?></strong></div><p><?php echo nl2br(utf8_htmlentities($match['description'])) ?></p><?php if ($match['stream_url']): ?><a class="btn btn-primary" href="<?php echo utf8_htmlentities($match['stream_url']) ?>" rel="noopener noreferrer"><?php echo $this->lang('Watch stream') ?></a><?php endif ?></article>
